(()=>{'use strict';
const channel='stack-lab-workspace-v1',routes={'/':'홈','/lab/':'배치','/units/':'초마신','/dealer-tiers/':'티어리스트 투표','/stages/':'스테이지','/wall/':'성벽','/rankings/':'랭킹','/updates/':'업데이트'},embedded=window.parent!==window,sourceRoute=location.pathname+location.search;
const send=value=>embedded?window.parent.postMessage({channel,...value},location.origin):receive(value,sourceRoute);
// Observe dedicated workers without changing their requests, responses or cancellation.
const taskWorkers=new Map;
window.addEventListener('stack-lab:control-task',({detail})=>{const worker=taskWorkers.get(detail.id);if(!worker)return;if(detail.action==='stop'){if(worker.stopWithResult){worker.stopWithResult();return;}worker.onmessage?.({data:{id:worker.job.requestId,error:'사용자가 계산을 중지했습니다.'}});worker.terminate();}else worker.prioritize?.();});
const NativeWorker=window.Worker;
if(NativeWorker)window.Worker=class extends NativeWorker{
 constructor(...args){super(...args);this.job=null;this.addEventListener('scheduler',({detail})=>{if(this.job&&['queued','paused','running'].includes(detail.state)){this.job.status=detail.state;this.job.queuePosition=detail.queuePosition;this.job.detail=detail.phase==='lookup'?'공용 DB 확인 중':detail.phase==='saving'?'완료 결과 DB 저장 중':detail.phase==='local'?'로컬 기기에서 계산 중':detail.state==='paused'?'다른 계산 후 자동 재개':detail.state==='queued'?'계산 순서 대기':'계산 중';send({type:'task',job:{...this.job}});}});this.addEventListener('message',({data})=>{const job=this.job;if(!job||data.id!==undefined&&job.requestId!==undefined&&data.id!==job.requestId)return;const progress=/progress|position-row|status/.test(data.kind||'')||!!data.refreshing;if(data.error){job.status='error';job.detail=data.error;}else if(progress){if(!['paused','queued'].includes(job.status))job.status='running';job.detail=data.message|| (data.evaluated!==undefined?Number(data.evaluated).toLocaleString('ko-KR')+'개 검토':data.row?.wave?data.row.wave+'라운드':data.wave?data.wave+'라운드':'계산 중');}else{job.status='done';job.detail=data.cacheSource==='shared-db'?'공용 DB 결과 재사용 · 결과를 확인하세요':data.sharedSaved===false?'로컬 계산 완료 · DB 저장 실패':data.sharedSaved?'로컬 계산 완료 · DB 저장 완료':'결과를 확인하세요';}const now=Date.now();if(!progress||now-(job.notified||0)>500){job.notified=now;send({type:'task',job:{...job}});}});this.addEventListener('error',()=>{if(this.job){this.job.status='error';this.job.detail='계산 오류';send({type:'task',job:{...this.job}});}});}
 postMessage(data,...args){const labels={compose:'배치 추천',stages:'스테이지 분석',recommend:'보석 추천',top:'보석 TOP',positions:'위치 비교','dealer-tier':'티어리스트 투표 분석',wall:'성벽 계산','wall-recommend':'성벽 추천',giant:'거인 계산',pressure:'수압 비교','clara-stacks':'클라라 비교'};if(labels[data?.kind]){this.job={id:crypto.randomUUID(),requestId:data.id,kind:data.kind,label:(data.slug?(window.CoopData?.UNIT_BY_ID?.get(data.slug)?.nameKo||document.querySelector('#unit-name')?.textContent||data.slug)+' · ':'')+labels[data.kind]+(data.kind==='top'?' 5':''),status:'running',detail:'계산 시작'};taskWorkers.set(this.job.id,this);send({type:'task',job:{...this.job}});}return super.postMessage(data,...args);}
 terminate(){if(['running','paused','queued'].includes(this.job?.status)){this.job.status='stopped';this.job.detail='현재까지 결과 확인';send({type:'task',job:{...this.job}});}return super.terminate();}
};
document.addEventListener('click',event=>{const a=event.target.closest('a[href]');if(!a||a.download||a.target&&a.target!=='_self'||event.defaultPrevented||event.button||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;const url=new URL(a.href,location.href);if(url.origin!==location.origin||!routes[url.pathname]||url.hash)return;event.preventDefault();send({type:'navigate',url:url.pathname+url.search});});
if(embedded)return;
const frames=new Map,jobs=new Map,pending=[],base=sourceRoute;let active=base,ready=false,ui;
function receive(data,route){if(!ready){pending.push([data,route]);return;}if(data.type==='navigate')navigate(data.url);if(data.type==='task'){jobs.set(data.job.id,{...data.job,route});while(jobs.size>30){const old=[...jobs].find(([,j])=>['done','error','stopped'].includes(j.status));if(!old)break;jobs.delete(old[0]);}render();}}
function navigate(path,push=true){const url=new URL(path,location.origin);if(url.origin!==location.origin||!routes[url.pathname])return;path=url.pathname+url.search;for(const d of document.querySelectorAll('dialog[open]'))d.close();const previous=active===base?window:frames.get(active)?.contentWindow;if(previous){previous.__stackWorkspaceVisible=false;previous.dispatchEvent(new Event('stack-lab:workspace-away'));}for(const frame of frames.values())frame.hidden=true;if(path!==base){let frame=frames.get(path);if(!frame){frame=document.createElement('iframe');frame.src=path;frame.title=routes[url.pathname];frame.className='workspace-frame';frames.set(path,frame);ui.prepend(frame);}frame.hidden=false;}active=path;const shown=path===base?window:frames.get(path)?.contentWindow;if(shown){shown.__stackWorkspaceVisible=true;shown.dispatchEvent(new Event('stack-lab:workspace-visible'));}window.StackLabCompute?.setActive(path);document.body.classList.toggle('workspace-away',path!==base);document.body.classList.toggle('workspace-viewing',path!==base);if(push)history.pushState({workspace:path},'',path);window.dispatchEvent(new CustomEvent('stack-lab:navigate',{detail:{path}}));render();}
function render(){if(!ready)return;const running=[...jobs.values()].filter(j=>['running','paused','queued'].includes(j.status)),done=[...jobs.values()].filter(j=>j.status==='done');ui.querySelector('#workspace-current').textContent=routes[new URL(base,location.origin).pathname]+(active===base?' 화면':'로 돌아가기');ui.querySelector('#workspace-tasks').textContent=running.length?'계산 '+running.length+'개 진행 중':done.length?'계산 결과 '+done.length+'개':'계산 상태';const list=ui.querySelector('#workspace-job-list');if(!ui.querySelector('#workspace-jobs').open)return;if(window.StackLabCompute)ui.querySelector('#workspace-efficiency').textContent='동시 계산 최대 '+window.StackLabCompute.limit+'개 · 중복 요청 '+window.StackLabCompute.stats.shared+'회 공유 · DB 결과 '+(window.StackLabCompute.stats.cacheHits||0)+'회 재사용 · 탐색 자동 대기 '+window.StackLabCompute.stats.pauses+'회';list.replaceChildren();const ordered=[...jobs.values()].sort((a,b)=>{const rank={running:0,queued:1,paused:2};return (rank[a.status]??3)-(rank[b.status]??3)||(a.queuePosition||0)-(b.queuePosition||0);});let waiting=0;for(const job of ordered){const row=document.createElement('div');row.className='workspace-job-row';const b=document.createElement('button');b.textContent=(job.status==='queued'?'대기 '+(job.queuePosition||++waiting)+'번 · ':'')+job.label+' · '+({running:'진행 중',paused:'자동 대기',queued:'순서 대기',done:'완료',error:'오류',stopped:'중지'}[job.status])+' · '+job.detail;b.onclick=()=>{navigate(job.route);const target=job.route===base?window:frames.get(job.route)?.contentWindow;target?.dispatchEvent(new CustomEvent('stack-lab:show-task',{detail:{kind:job.kind}}));};if(['running','queued','paused'].includes(job.status)){for(const [action,label]of [['priority','우선 계산'],['stop','중지']]){const control=document.createElement('button');control.textContent=label;control.onclick=event=>{event?.stopPropagation();const target=job.route===base?window:frames.get(job.route)?.contentWindow;target?.dispatchEvent(new CustomEvent('stack-lab:control-task',{detail:{id:job.id,action}}));};row.append(control);}}row.prepend(b);list.append(row);}if(!jobs.size)list.textContent='계산을 시작하면 이곳에서 진행 상태와 결과를 확인할 수 있습니다.';}
function mount(){ui=document.createElement('section');ui.id='workspace-shell';ui.innerHTML='<div class="workspace-dock"><button id="workspace-menu">다른 도구</button><button id="workspace-current" aria-label="현재 도구"></button><button id="workspace-tasks" aria-haspopup="dialog">계산 상태</button></div><dialog id="workspace-tools"><header><b>다른 항목 보기</b><button data-workspace-close>닫기</button></header><p>계산 중인 화면은 유지됩니다. 각 도구를 다시 열면 작업하던 화면으로 돌아옵니다.</p><div id="workspace-route-list"></div></dialog><dialog id="workspace-jobs"><header><b>계산 진행 · 결과</b><button data-workspace-close>닫기</button></header><p id="workspace-efficiency"></p><div id="workspace-job-list"></div></dialog>';document.body.append(ui);document.body.classList.add('has-workspace');ready=true;if(!embedded)fetch('/api/visitors',{method:'POST',keepalive:true}).catch(()=>{});for(const [data,route]of pending.splice(0))receive(data,route);for(const [path,label]of Object.entries(routes)){const row=document.createElement('div');row.className='workspace-job-row';const b=document.createElement('button');b.textContent=label;b.onclick=()=>navigate(path);ui.querySelector('#workspace-route-list').append(b);}ui.querySelector('#workspace-menu').onclick=()=>ui.querySelector('#workspace-tools').showModal();ui.querySelector('#workspace-tasks').onclick=()=>{ui.querySelector('#workspace-jobs').showModal();render();};ui.querySelector('#workspace-current').onclick=()=>navigate(base);for(const b of ui.querySelectorAll('[data-workspace-close]'))b.onclick=()=>b.closest('dialog').close();render();}
window.addEventListener('message',event=>{if(event.origin!==location.origin||event.data?.channel!==channel)return;const frame=[...frames].find(([,f])=>f.contentWindow===event.source);if(frame)receive(event.data,frame[0]);});window.addEventListener('popstate',event=>navigate(event.state?.workspace||base,false));if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',mount,{once:true});else mount();
})();
